async private Task<MaaJobStatus> TryRunTasksAsync(MaaTasker? maa, string? task, string? param, CancellationToken token)
{
    if (maa == null || task == null) return MaaJobStatus.Invalid;
    token.ThrowIfCancellationRequested();
    void ClearHistory() => MFAAvalonia.Services.NativeTaskHistory.ClearIfIdle(
        maa, () => !maa.IsRunning && !maa.IsStopping, maa.ClearCache,
        message => LoggerHelper.Warning(message));
    // Reclaim history left by a previous cancelled wait only after it is idle.
    ClearHistory();
    try
    {
        using var history = MFAAvalonia.Services.NativeTaskHistory.Acquire(maa);
        var job = maa.AppendTask(task, param ?? "{}");
        TelemetryService.SetActiveTaskId(InstanceId, job.Id);
        return await TaskManager.RunTaskAsync(() => job.Wait(), token, (ex) => throw ex,
            name: "队列任务", catchException: true, shouldLog: false);
    }
    finally
    {
        // The status is already copied; synchronous native callbacks finished.
        // A cancelled wait can still own an active native job: skip it then.
        ClearHistory();
    }
}
